    private void programs(){pageTitle("Авто программы",true);programs=repo.load();LinearLayout p=page();Button add=primary("+ Новая программа");add.setOnClickListener(new View.OnClickListener(){public void onClick(View v){AutoProgram x=ProgramRepository.def();x.name="Новая программа "+(programs.size()+1);programs.add(x);repo.save(programs);edit(programs.size()-1);}});p.addView(add,margin());for(int i=0;i<programs.size();i++){final int idx=i;final AutoProgram pr=programs.get(i);LinearLayout c=card();c.addView(text(pr.name,19,true));c.addView(text(summary(pr),13,false));LinearLayout row=new LinearLayout(this);Button run=modeBtn("Запустить",GREEN),ed=modeBtn("Изменить",BLUE),cp=modeBtn("Копия",ORANGE);run.setOnClickListener(new View.OnClickListener(){public void onClick(View v){start(idx);}});ed.setOnClickListener(new View.OnClickListener(){public void onClick(View v){edit(idx);}});cp.setOnClickListener(new View.OnClickListener(){public void onClick(View v){programs.add(pr.copy());repo.save(programs);programs();}});row.addView(run,weight());row.addView(ed,weight());row.addView(cp,weight());c.addView(row);p.addView(c,margin());}LinearLayout io=new LinearLayout(this);Button ex=button("Экспорт"),im=button("Импорт");ex.setOnClickListener(new View.OnClickListener(){public void onClick(View v){exportJson();}});im.setOnClickListener(new View.OnClickListener(){public void onClick(View v){importJson();}});io.addView(ex,weight());io.addView(im,weight());p.addView(io);setPage(p);}
    private void edit(final int idx){if(idx<0||idx>=programs.size())return;pageTitle("Редактор Auto",true);final AutoProgram pr=programs.get(idx);LinearLayout p=page();final EditText name=editText("Название",InputType.TYPE_CLASS_TEXT);name.setText(pr.name);p.addView(name);final CheckBox[] en=new CheckBox[4],stop=new CheckBox[4];final EditText[] sn=new EditText[4],target=new EditText[4],tol=new EditText[4],stable=new EditText[4],hold=new EditText[4],probe=new EditText[4];final Spinner[] cond=new Spinner[4],act=new Spinner[4];String[] cs={"Только время","Только K","Только T","Время ИЛИ K","Время ИЛИ T","Время И K","Время И T"};String[] as={"Щуп сразу","Щуп после готовности камеры"};for(int i=0;i<4;i++){AutoStage s=pr.stages.get(i);LinearLayout c=card();en[i]=check("Этап "+(i+1)+" включён");en[i].setChecked(s.enabled);c.addView(en[i]);sn[i]=editText("Название этапа",1);sn[i].setText(s.name);c.addView(sn[i]);target[i]=num("Камера, целые °C",s.chamberTarget);tol[i]=num("Допуск ±°C",s.tolerance);stable[i]=num("Стабилизация, сек",s.stableSeconds);hold[i]=num("Выдержка, мин",s.holdMs/60000.0);c.addView(target[i]);c.addView(tol[i]);c.addView(stable[i]);c.addView(hold[i]);cond[i]=spin(cs);cond[i].setSelection(ci(s.finishCondition));c.addView(cond[i]);probe[i]=num("Температура щупа",s.probeTarget);c.addView(probe[i]);act[i]=spin(as);act[i].setSelection(s.probeActivation==AutoStage.ProbeActivation.IMMEDIATE?0:1);c.addView(act[i]);stop[i]=check("После этапа СТОП");stop[i].setChecked(s.stopAfter);c.addView(stop[i]);p.addView(c,margin());}LinearLayout actions=new LinearLayout(this);Button save=modeBtn("Сохранить",GREEN),run=modeBtn("Сохранить+Старт",BLUE),del=modeBtn("Удалить",RED);View.OnClickListener sv=new View.OnClickListener(){public void onClick(View v){try{pr.name=name.getText().toString().trim();boolean any=false;for(int i=0;i<4;i++){AutoStage s=pr.stages.get(i);s.enabled=en[i].isChecked();any|=s.enabled;s.name=sn[i].getText().toString().trim();s.chamberTarget=d(target[i]);if(Math.abs(s.chamberTarget-Math.rint(s.chamberTarget))>.0001)throw new Exception("Камера должна быть целым числом");s.tolerance=d(tol[i]);s.stableSeconds=(int)d(stable[i]);s.holdMs=(long)(d(hold[i])*60000);s.finishCondition=ca(cond[i].getSelectedItemPosition());s.probeTarget=d0(probe[i]);s.probeActivation=act[i].getSelectedItemPosition()==0?AutoStage.ProbeActivation.IMMEDIATE:AutoStage.ProbeActivation.AFTER_CHAMBER_READY;s.stopAfter=stop[i].isChecked();}if(!any)throw new Exception("Нет активных этапов");repo.save(programs);if(v==run)start(idx);else programs();}catch(Exception e){toast("Ошибка: "+e.getMessage());}}};save.setOnClickListener(sv);run.setOnClickListener(sv);del.setOnClickListener(new View.OnClickListener(){public void onClick(View v){if(programs.size()<=1){toast("Нужна хотя бы одна программа");return;}programs.remove(idx);repo.save(programs);programs();}});actions.addView(save,weight());actions.addView(run,weight());actions.addView(del,weight());p.addView(actions);setPage(p);}
