    private void mqttPage(){pageTitle("MQTT",true);LinearLayout p=page();final EditText broker=field("Broker",prefs.getString("broker",""),1),port=field("Port",prefs.getString("port","1883"),2),status=field("Status topic",prefs.getString("topic","homesmoke/status"),1),cmd=field("Command topic",prefs.getString("cmd_topic","homesmoke/cmd"),1),ack=field("ACK topic",prefs.getString("ack_topic","homesmoke/ack"),1),user=field("Логин",prefs.getString("user",""),1),pass=field("Пароль",prefs.getString("pass",""),1);p.addView(broker);p.addView(port);p.addView(status);p.addView(cmd);p.addView(ack);p.addView(user);p.addView(pass);final CheckBox tls=check("TLS (если поддерживает Android 4 прошивка)"),ac=check("Автоподключение");tls.setChecked(prefs.getBoolean("tls",false));ac.setChecked(prefs.getBoolean("mqtt_auto",false));p.addView(tls);p.addView(ac);Button connect=primary("Сохранить и подключить");connect.setOnClickListener(new View.OnClickListener(){public void onClick(View v){if(ok()){service.mqttConfig(s(broker),s(port),s(status),s(cmd),s(ack),s(user),s(pass),tls.isChecked(),ac.isChecked());service.startMqtt();}}});p.addView(connect,margin());Button disc=button("Отключить MQTT");disc.setOnClickListener(new View.OnClickListener(){public void onClick(View v){if(ok())service.stopMqtt();}});p.addView(disc,margin());TextView n=text("Android 4 Legacy хранит MQTT пароль локально без Android Keystore. Для старого планшета предпочтителен доверенный LAN/VPN. TLS зависит от прошивки.",12,false);p.addView(n,margin());setPage(p);}
    private void diagnostics(){pageTitle("Диагностика",true);LinearLayout p=page();Telemetry x=state==null?null:state.t;LinearLayout c=card();c.addView(text("BT: "+(state!=null&&state.bt?"OK":"нет"),14,true));c.addView(text("MQTT: "+(state==null?"—":state.mqttText),14,false));c.addView(text("Auto: "+(state==null?"—":state.auto),14,false));if(x!=null){c.addView(text("Камера "+v(x.chamber)+"  K "+v(x.probeK)+"  T "+v(x.probeT),14,false));TextView raw=text(x.raw,11,false);raw.setTypeface(Typeface.MONOSPACE);raw.setTextIsSelectable(true);c.addView(raw);}p.addView(c,margin());setPage(p);}
    private void drawer(){if(drawer!=null&&drawer.isShowing()){drawer.dismiss();return;}FrameLayout o=new FrameLayout(this);o.setBackgroundColor(Color.argb(80,0,0,0));final LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);p.setBackgroundColor(Color.WHITE);TextView h=text("HomeSmoke Legacy",20,true);h.setTextColor(Color.WHITE);h.setGravity(Gravity.CENTER_VERTICAL);h.setPadding(dp(18),0,0,0);h.setBackgroundColor(BLUE);p.addView(h,new LinearLayout.LayoutParams(-1,dp(64)));item(p,"Монитор",new Runnable(){public void run(){showMonitor();}});item(p,"Авто программы",new Runnable(){public void run(){programs();}});item(p,"PID",new Runnable(){public void run(){pidPage();}});item(p,"Bluetooth / Настройки",new Runnable(){public void run(){settings();}});item(p,"MQTT",new Runnable(){public void run(){mqttPage();}});item(p,"Диагностика",new Runnable(){public void run(){diagnostics();}});item(p,"СТОП",new Runnable(){public void run(){stopConfirm();}});FrameLayout.LayoutParams pp=new FrameLayout.LayoutParams(Math.min(dp(290),(int)(getResources().getDisplayMetrics().widthPixels*.86f)),-1,Gravity.RIGHT);o.addView(p,pp);o.setOnClickListener(new View.OnClickListener(){public void onClick(View v){drawer.dismiss();}});p.setOnClickListener(new View.OnClickListener(){public void onClick(View v){}});drawer=new PopupWindow(o,-1,-1,true);drawer.setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));drawer.showAtLocation(menu,Gravity.TOP|Gravity.LEFT,0,0);}
