    public void onState(final LegacyHomeSmokeService.State s){runOnUiThread(new Runnable(){public void run(){state=s;render(s);}});}private void render(LegacyHomeSmokeService.State s){if(bt!=null){bt.setBackgroundDrawable(round(s!=null&&s.bt?GREEN:Color.DKGRAY,10));}if(camera==null)return;Telemetry x=s==null?null:s.t;camera.setText(x==null?"— °C":v(x.chamber)+" °C");k.setText(x==null?"— °C":v(x.probeK)+" °C");t.setText(x==null?"— °C":v(x.probeT)+" °C");setpoint.setText(x==null?"Уставка: —":"Уставка: "+v(x.chamberSetpoint)+" °C");power.setText(x==null?"— %":v(x.heaterPower)+" %");mode.setText(x==null?"—":(x.mode==0?"Ручной":x.mode==1?"PID":"СТОП"));last.setText(x==null?"—":x.lastCommand);auto.setText(s==null?"—":s.auto);error.setText(s==null?"":s.lastError);}
    private void start(int i){if(ok()&&service.startAuto(programs.get(i)))showMonitor();else if(service!=null)toast(service.state().lastError);}private void cameraClick(){if(!ok()||state==null||state.t==null)return;if(service.autoRunning()){toast("Уставкой управляет Auto");return;}final boolean pid=state.t.mode==1,manual=state.t.mode==0;if(!pid&&!manual){toast("Выберите PID или РУЧНОЙ");return;}final EditText e=editText("Целое 0..100",InputType.TYPE_CLASS_NUMBER);new AlertDialog.Builder(this).setTitle(pid?"Температура камеры":"Мощность ТЭНа").setView(e).setPositiveButton("Применить",new android.content.DialogInterface.OnClickListener(){public void onClick(android.content.DialogInterface d,int w){try{double q=d(e);if(q<0||q>100||Math.abs(q-Math.rint(q))>.001)throw new Exception();if(pid)service.setTemp(q);else service.setPower(q);}catch(Exception ex){toast("Нужно целое 0..100");}}}).setNegativeButton("Отмена",null).show();}
